	["{quest:1123}'s house stands in {area:2361}, a short walk from {npc:11802}: hand her the letter from {zone:1457} on the way to the flight master."] = "{quest:1123} evi {area:2361} köyünde, {npc:11802} yanından kısa bir yürüyüş mesafesinde: uçuş ustasına giderken {zone:1457} şehrinden gelen mektubu ona ver.",
	-- {npc:13220} Layo Starstrike · {zone:1451} Silithus
	["For {npc:13220} in {zone:1451}, on the next guide: keep it"] = "Sonraki rehberde {zone:1451} bölgesindeki {npc:13220} için: sakla",

	-- Step 50: Fly to Everlook
	-- {area:2255} Everlook
	["Fly to {area:2255}"] = "Uç: {area:2255}",
	-- {area:493} Moonglade · {area:2255} Everlook · {npc:249235} Kaylaena Springwhisper
	["South to {area:493}'s flight master (the Alliance's at the southern end of the valley, the Horde's at its south-western end) and fly to {area:2255} for {npc:249235}'s parts order."] = "Güneye, {area:493} uçuş ustasına git (Alliance'ınki vadinin güney ucunda, Horde'unki güneybatı ucunda) ve {npc:249235} adlı NPC'nin parça siparişi için {area:2255} kasabasına uç.",

	-- Step 51: Nami
	-- {npc:228216} Nami · {area:2255} Everlook · {area:16853} Tainted Foothills · {npc:249235} Kaylaena Springwhisper
	["{npc:228216} stands between {area:2255}'s two flight masters. Her crate holds fragile cells that fizzle out in time and when knocked about: fly straight back to the {area:16853} and take it to {npc:249235} without detours or fights (about four minutes in the recording). If it fizzles out anyway, {npc:228216} fills it again."] = "{npc:228216}, {area:2255} kasabasının iki uçuş ustasının arasında duruyor. Sandığında zamanla ve sarsılınca sönen kırılgan hücreler var: doğruca {area:16853} bölgesine geri uç ve sandığı sapmadan, dövüşmeden {npc:249235} yanına götür (kayıtta yaklaşık dört dakika). Yine de sönerse {npc:228216} onu yeniden doldurur.",

	-- Step 52: Fly to the Tainted Foothills
	-- {area:16853} Tainted Foothills
	["Fly to the {area:16853}"] = "{area:16853} bölgesine uç",

	-- Step 53: Kaylaena Springwhisper's workshop
	-- {npc:260626} Bluebell
	["North from {npc:260626} to the workshop, crate first. Watch for Ghansurok, the elite chimaera (level 61) that prowls around the workshop."] = "{npc:260626} yanından kuzeye, atölyeye git, önce sandık. Atölyenin çevresinde dolaşan elit chimaera Ghansurok'a (seviye 61) dikkat et.",
	["deliver the crate before it fizzles"] = "sandığı sönmeden teslim et",
	-- {quest:92011} Rubble Rummage · {area:16866} Dae'gun
	["{quest:92011}: in {area:16866}, later in this guide; keep it"] = "{quest:92011}: bu rehberde daha sonra {area:16866} içinde. Sakla",

	-- Step 54: Ketharas
	["South-east to the Hermit's Abode."] = "Güneydoğuya, Hermit's Abode'a git.",
	-- {quest:96930} The Capricious Corvid · {npc:257753} Curious Crow
	["{quest:96930}: for the {npc:257753}, later in this guide"] = "{quest:96930}: bu rehberde daha sonra {npc:257753} için",
	-- {quest:92171} Taking to New Heights · {npc:254131} Skylord Omnuron
	["{quest:92171}: for {npc:254131}, later in this guide"] = "{quest:92171}: bu rehberde daha sonra {npc:254131} için",

	-- Step 55: The Curious Crow
	-- {npc:257753} Curious Crow · {area:17050} Felblood Scar
	["West across the foothills, past the ancients' outpost, to the {npc:257753} at the southern end of {area:17050}."] = "Etekleri batıya geçip ancient'ların karakolunu geçerek {area:17050} kesiminin güney ucundaki {npc:257753} yanına git.",
	-- {quest:96931} Heading Up the Mountain · {area:17145} Cradle of Tranquility
	["{quest:96931}: for the {area:17145}, later in this guide"] = "{quest:96931}: bu rehberde daha sonra {area:17145} için",

	-- Step 56: Malorne's Retreat
	-- {area:17144} Malorne's Retreat · {npc:249549} Fenwick Togglespring
	["West along the southern slopes to {area:17144}: {npc:249549}, a gnome test pilot, hangs tangled up in a tree. A sturdy branch lies just south of him."] = "Güney yamaçları boyunca batıya, {area:17144} kesimine git: gnome test pilotu {npc:249549} bir ağaca dolanmış asılı duruyor. Sağlam bir dal hemen güneyinde yatıyor.",
	-- {npc:254501} Tree Branch
	["{npc:254501}, above Fenwick's head"] = "{npc:254501}, Fenwick'in başının üstünde",

	-- Step 57: Fenwick's survival pack
	["Fenwick's survival pack"] = "Fenwick'in hayatta kalma çantası",
	["His pack fell just north of the tree. Open it, then wait half a minute while its safety lock discharges before you open it again."] = "Çantası ağacın hemen kuzeyine düştü. Aç, sonra yeniden açmadan önce güvenlik kilidi boşalırken yarım dakika bekle.",

	-- Step 58: Brerufa
	-- {npc:256978} Brerufa
	["North-west to Barkskin Burrow, the furbolgs' den in the hillside: {npc:256978} waits just north of its mouth. The Barkskin furbolgs show as hostile until your standing with them improves, but none of them attacked in the recording: the Deadwood furbolgs in the camps around are the ones to fight. {npc:256978} offers more only once this first quest is handed in."] = "Kuzeybatıya, yamaçtaki furbolg ini Barkskin Burrow'a git: {npc:256978} ağzının hemen kuzeyinde bekliyor. Barkskin furbolg'ları onlarla itibarın artana kadar düşman görünür, ama kayıtta hiçbiri saldırmadı: dövüşülecekler çevredeki kamplardaki Deadwood furbolg'ları. {npc:256978} daha fazlasını ancak bu ilk görev teslim edilince verir.",

	-- Step 59: Deadwood Den Guardians
	-- plural, as words: Deadwood Den Guardians = {npc:252063} Deadwood Den Guardian
	["Deadwood Den Guardians"] = "Deadwood Den Guardian yaratıkları",
	-- {npc:256978} Brerufa
	["The Deadwood furbolgs camp on the slopes north and east of {npc:256978}: kill their Den Guardians."] = "Deadwood furbolg'ları {npc:256978} yanının kuzeyindeki ve doğusundaki yamaçlarda kamp kurmuş: Den Guardian'larını öldür.",

	-- Step 61: Osi Mistpaw
	-- {npc:256646} Osi Mistpaw
	["Inside the burrow: {npc:256646} at the far end."] = "Yuvanın içinde: en uçta {npc:256646}.",

	-- Step 62: Bear berries
	["Bear berries"] = "Ayı meyveleri",
	-- {npc:256978} Brerufa
	["The bear berries grow on the slopes around the burrow: a few on the hill north of {npc:256978}, most of them east of the burrow.\nCareful: Grimroot, an elite treant (level 60), walks the slopes west of the burrow, around 16-20,58-66: give him room."] = "Ayı meyveleri yuvanın çevresindeki yamaçlarda yetişiyor: birkaçı {npc:256978} yanının kuzeyindeki tepede, çoğu yuvanın doğusunda.\nDikkat: elit treant Grimroot (seviye 60), yuvanın batısındaki yamaçlarda, 16-20,58-66 civarında yürüyor: ondan uzak dur.",

	-- Step 63: Barkskin Burrow
	["Barkskin Burrow"] = "Barkskin Burrow",
	-- {npc:260661} Suma Mossmane · {npc:256660} Thobon Sapclaw · {area:16848} Elderwild · {area:16867} Shrine of Aviana
	["Back to Osi, then the two elders at the back of the burrow. {npc:260661} stands beside Osi, {npc:256660} a little north-west of them, where the recording met him. {npc:260661}'s moss grows around {area:16848}, later in this guide; {npc:256660}'s amulets come from the harpies at the {area:16867}, also later in this guide, and you bring both back here then."] = "Osi'ye, sonra yuvanın arka tarafındaki iki yaşlıya dön. {npc:260661} Osi'nin yanında, {npc:256660} da onların biraz kuzeybatısında, kayıtta karşılaşılan yerde duruyor. {npc:260661} adlı NPC'nin yosunu bu rehberde daha sonra {area:16848} çevresinde yetişir. {npc:256660} adlı NPC'nin muskaları da yine daha sonra {area:16867} kesimindeki harpy'lerden gelir. İkisini de o zaman buraya geri getirirsin.",
	-- {quest:93826} Deal Dread to Deadwood
	["{quest:93826}: on your way back here later; keep it"] = "{quest:93826}: daha sonra buraya dönerken. Sakla",

	-- Step 64: The Western Post
	-- {area:16848} Elderwild · {npc:244517} Sefira Everbright · {npc:249968} Hnaz Blunderflame · {npc:244511} Zet'gan · {npc:244512} Ortak Lomgok
	["North up the valley to {area:16848}, where the Alliance outpost ({npc:244517}, {npc:249968}) and the Horde's ({npc:244511}, {npc:244512}) stand next to each other."] = "Vadiden kuzeye, Alliance karakolunun ({npc:244517}, {npc:249968}) ve Horde karakolunun ({npc:244511}, {npc:244512}) yan yana durduğu {area:16848} kesimine git.",

	-- Step 65: The Western Post
	-- {area:16848} Elderwild · {npc:244511} Zet'gan · {npc:244512} Ortak Lomgok · {npc:265788} Kal'tinzan
	["North up the valley to {area:16848}, where the Horde outpost ({npc:244511}, {npc:244512}, {npc:265788}) and the Alliance's stand next to each other."] = "Vadiden kuzeye, Horde karakolunun ({npc:244511}, {npc:244512}, {npc:265788}) ve Alliance karakolunun yan yana durduğu {area:16848} kesimine git.",

	-- Step 67: Elderwild
	-- {area:16848} Elderwild
	["The two outposts of {area:16848}."] = "{area:16848} kesiminin iki karakolu.",
	-- {npc:244512} Ortak Lomgok · {quest:96616} Herbs for the Bruised and Weary · {area:16868} Mourning's Rest
	["{npc:244512}: {quest:96616}, on the way back from {area:16868}"] = "{npc:244512}: {quest:96616}, {area:16868} dönüşünde",

	-- Step 68: Final Death
	-- {quest:92591} Final Death · {npc:260148} Scourge Reanimator · {area:16868} Mourning's Rest
	["{quest:92591}'s {npc:260148} is level 59-60: this guide burns its bone pile once you are 58, on one of its two passes through {area:16868}."] = "{quest:92591} görevinin {npc:260148} yaratığı seviye 59-60: bu rehber, {area:16868} içinden iki geçişinden birinde, sen 58 olunca kemik yığınını yakar.",

	-- Step 69: Final Death
	-- {quest:92592} Final Death · {npc:260148} Scourge Reanimator · {area:16868} Mourning's Rest
	["{quest:92592}'s {npc:260148} is level 59-60: this guide burns its bone pile once you are 58, on one of its two passes through {area:16868}."] = "{quest:92592} görevinin {npc:260148} yaratığı seviye 59-60: bu rehber, {area:16868} içinden iki geçişinden birinde, sen 58 olunca kemik yığınını yakar.",

	-- Step 70: Final Death
	-- {npc:260148} Scourge Reanimator · {quest:92591} Final Death
	["A group choice at your level: the {npc:260148} that answers {quest:92591}'s bone pile is level 59-60."] = "Senin seviyende bir grup tercihi: {quest:92591} kemik yığınına gelen {npc:260148} seviye 59-60.",

	-- Step 71: Final Death
	-- {npc:260148} Scourge Reanimator · {quest:92592} Final Death
	["A group choice at your level: the {npc:260148} that answers {quest:92592}'s bone pile is level 59-60."] = "Senin seviyende bir grup tercihi: {quest:92592} kemik yığınına gelen {npc:260148} seviye 59-60.",

	-- Step 72: Moonveil Moss
	-- {npc:260661} Suma Mossmane · {area:16848} Elderwild
	["The moss for {npc:260661} grows around {area:16848}: by the outposts and on the slopes north of them."] = "{npc:260661} için yosun {area:16848} çevresinde yetişiyor: karakolların yanında ve kuzeylerindeki yamaçlarda.",

	-- Step 73: Eluneth
	-- {npc:264089} Eluneth · {area:16868} Mourning's Rest
	["South-east to {npc:264089} on the slope above {area:16868}."] = "Güneydoğuya, {area:16868} kesiminin yukarısındaki yamaçta duran {npc:264089} yanına git.",

	-- Step 74: Owl feathers
	["Owl feathers"] = "Baykuş tüyleri",
	-- {npc:264089} Eluneth · {area:16848} Elderwild
	-- plural, as words: Hyjal Owls = {npc:249053} Hyjal Owl · Death Wailers = {npc:249226} Death Wailer
	["The Hyjal Owls roost on the slopes between {npc:264089} and Barkskin Burrow: their feathers are for {area:16848}.\nCareful: Death Wailers (61, rare elites) drift over the western slopes: give them a wide berth.\nCareful: Grimroot, an elite treant (level 60), walks the slopes beside {npc:264089}. He leaves you alone unless you hit him: don't, and pull the owls away from his path."] = "Hyjal Owl yaratıkları {npc:264089} ile Barkskin Burrow arasındaki yamaçlarda tünüyor: tüyleri {area:16848} için.\nDikkat: Death Wailer yaratıkları (61, rare elit) batı yamaçlarının üstünde süzülüyor: onlardan iyice uzak dur.\nDikkat: elit treant Grimroot (seviye 60) {npc:264089} yanındaki yamaçlarda yürüyor. Ona vurmazsan sana bulaşmaz: vurma, baykuşları onun yolundan uzağa çek.",

	-- Step 75: Unmarked Grave
	-- {area:16868} Mourning's Rest
	-- plural, as words: Fleshflay Raveners = {npc:249228} Fleshflay Ravener
	["At the northern end of {area:16868}: something has dug up the grave. The Fleshflay Raveners around it carry what was taken."] = "{area:16868} kesiminin kuzey ucunda: bir şey mezarı kazmış. Çevresindeki Fleshflay Ravener yaratıkları alınanı taşıyor.",

	-- Step 76: Mourning's Rest
	-- {area:16868} Mourning's Rest · {area:16848} Elderwild
	-- plural, as words: Fleshflay Raveners = {npc:249228} Fleshflay Ravener · Forgotten Soldiers = {npc:249247} Forgotten Soldier · Death Wailers = {npc:249226} Death Wailer
	["The Scourge hold the ruins of {area:16868}, east of {area:16848}: Fleshflay Raveners and Forgotten Soldiers everywhere, Eternal Sentries among them.\nCareful: Death Wailers (61, rare elites) drift over {area:16868}: keep out of their way.\nCareful: Grimroot, the elite treant (level 60), walks the slopes on the way in. He leaves you alone unless you hit him: give him room."] = "Scourge, {area:16848} kesiminin doğusundaki {area:16868} harabelerini tutuyor: her yerde Fleshflay Ravener ve Forgotten Soldier yaratıkları, aralarında Eternal Sentry'ler.\nDikkat: Death Wailer yaratıkları (61, rare elit) {area:16868} üstünde süzülüyor: yollarından çekil.\nDikkat: elit treant Grimroot (seviye 60) giriş yolundaki yamaçlarda yürüyor. Ona vurmazsan sana bulaşmaz: ondan uzak dur.",

	-- Step 77: Final Death
	-- {area:16868} Mourning's Rest · {item:274411} Survivor's Torch · {npc:260148} Scourge Reanimator
	["Burn the bone pile at the south-eastern end of {area:16868} with the {item:274411}: the {npc:260148} that answers carries the amulet.\nCareful: the {npc:260148} is level 59-60: burn the bone pile last, at full health, with the ruins around it cleared."] = "{area:16868} kesiminin güneydoğu ucundaki kemik yığınını {item:274411} ile yak: gelen {npc:260148} muskayı taşıyor.\nDikkat: {npc:260148} seviye 59-60: kemik yığınını en son, canın tamken ve çevresindeki harabeleri temizledikten sonra yak.",

	-- Step 78: Final Death
	-- {npc:260148} Scourge Reanimator
	["A group choice below level 58: the {npc:260148} that answers the burnt bone pile is level 59-60. Grouping up is advised; alone, this guide comes back past the pile later."] = "Seviye 58'in altında bir grup tercihi: yakılan kemik yığınına gelen {npc:260148} seviye 59-60. Grup kurman önerilir. Yalnızsan bu rehber daha sonra yığının yanından yine geçer.",

	-- Step 79: Eluneth and the veteran
	-- {npc:264089} Eluneth
	["{npc:264089} and the veteran"] = "{npc:264089} ve gazi",
	-- {npc:264089} Eluneth · {npc:255009} Veteran of the Third War · {area:16868} Mourning's Rest
	["Back to {npc:264089}, then the ghostly {npc:255009} at {area:16868}'s western edge, where the recording met him, on your way west."] = "{npc:264089} yanına dön, sonra batıya giderken {area:16868} kesiminin batı kenarında, kayıtta karşılaşılan yerde hayalet {npc:255009} yanına git.",

	-- Step 80: Hyjal Silphium
	-- {area:16868} Mourning's Rest · {npc:244512} Ortak Lomgok · {area:16848} Elderwild
	-- plural, as words: Death Wailers = {npc:249226} Death Wailer
	["North-east up the slope from the veteran, north of {area:16868}: {npc:244512}'s silphium grows in the meadows there, where the Horde players in our recordings picked it. Then ride west to {area:16848}.\nCareful: Death Wailers (61, rare elites) drift over these slopes: keep out of their way."] = "Gazinin yanından yamaçtan kuzeydoğuya çık, {area:16868} kesiminin kuzeyine git: {npc:244512} adlı NPC'nin silphium'u oradaki çayırlarda, kayıtlarımızdaki Horde oyuncularının topladığı yerde yetişiyor. Sonra batıya, {area:16848} kesimine sür.\nDikkat: Death Wailer yaratıkları (61, rare elit) bu yamaçların üstünde süzülüyor: yollarından çekil.",

	-- Step 81: Elderwild
	["West to the Alliance outpost."] = "Batıya, Alliance karakoluna git.",

	-- Step 83: To the Summit of Eternity
	-- {quest:91688} To the Summit of Eternity · {npc:254915} Thisalee Crow
	["{quest:91688}: for {npc:254915}, later in this guide; keep it"] = "{quest:91688}: bu rehberde daha sonra {npc:254915} için. Sakla",

	-- Step 84: Daythor Brellan and Sefira Everbright
	-- {npc:264521} Daythor Brellan · {npc:244517} Sefira Everbright
	["{npc:264521} and {npc:244517}"] = "{npc:264521} ve {npc:244517}",
	-- {npc:244517} Sefira Everbright · {npc:264521} Daythor Brellan
	["The worker {npc:244517} means is a peasant just north of her; {npc:264521} stands between them."] = "{npc:244517} adlı NPC'nin söylediği işçi, hemen kuzeyindeki bir köylü. {npc:264521} ikisinin arasında duruyor.",
	-- {quest:94832} Belle's Ring · {npc:2329} Michelle Belle · {area:87} Goldshire
	["{quest:94832}: {npc:2329} at the Lion's Pride Inn in {area:87}; take it only if you'll pass by"] = "{quest:94832}: {area:87} kasabasındaki Lion's Pride Inn'de {npc:2329}. Yalnız oradan geçeceksen al",

	-- Step 85: Elderwild
	-- {npc:244511} Zet'gan · {npc:244512} Ortak Lomgok · {npc:265788} Kal'tinzan
	["West to the Horde outpost: {npc:244511}, then {npc:244512} and {npc:265788} beside him."] = "Batıya, Horde karakoluna git: önce {npc:244511}, sonra yanındaki {npc:244512} ve {npc:265788}.",
	-- {npc:265788} Kal'tinzan · {quest:91794} Flags of Our Forebears · {area:16866} Dae'gun
	["{npc:265788}: {quest:91794}: the flag and the heraldry are in {area:16866}, later in this guide; keep it"] = "{npc:265788}: {quest:91794}: bayrak ve arma bu rehberde daha sonra {area:16866} içinde. Sakla",

	-- Step 86: Maruke and Enho Runehoof
	-- {npc:265895} Maruke · {npc:265862} Enho Runehoof
	["{npc:265895} and {npc:265862}"] = "{npc:265895} ve {npc:265862}",
	-- {npc:244512} Ortak Lomgok · {npc:265895} Maruke · {area:16848} Elderwild · {npc:265862} Enho Runehoof
	["{npc:244512}'s poultice is for two of the outpost's wounded: {npc:265895} lies at the north end of {area:16848}, {npc:265862} just south of {npc:244512}."] = "{npc:244512} adlı NPC'nin lapası karakolun iki yaralısı için: {npc:265895} {area:16848} kesiminin kuzey ucunda, {npc:265862} de {npc:244512} yanının hemen güneyinde yatıyor.",

	-- Step 87: Head Scratcher
	-- {quest:92446} Head Scratcher · {npc:244511} Zet'gan
	["{quest:92446} is elite (level 60 in our data): grouping up is advised. {npc:244511}'s rabbit carcass lures him out in the woods by the Deadwood camps south-east of here, on part 3's way back to Barkskin Burrow; his claws come back here at the end of this guide."] = "{quest:92446} elit (verimizde seviye 60): grup kurman önerilir. {npc:244511} adlı NPC'nin tavşan leşi onu buranın güneydoğusundaki Deadwood kamplarının yanındaki ormanda, 3. kısmın Barkskin Burrow dönüşünde dışarı çeker. Pençelerini bu rehberin sonunda buraya geri getirirsin.",

	-- Step 88: The overlook
	["The overlook"] = "Gözetleme noktası",
	["West to the overlook above the valley: the veteran's old scabbard lies there. Hand his quest in at the scabbard and take the next from it, then use the scabbard in your bags to call his spirit and listen to his story."] = "Batıya, vadinin yukarısındaki gözetleme noktasına git: gazinin eski kını orada yatıyor. Görevini kında teslim edip sonrakini kından al, sonra ruhunu çağırıp hikâyesini dinlemek için çantandaki kını kullan.",

	-- Step 89: Shalla'kal and Galvinquam Leafsyre
	-- {npc:255683} Shalla'kal · {npc:267109} Galvinquam Leafsyre
	["{npc:255683} and {npc:267109}"] = "{npc:255683} ve {npc:267109}",
	-- {area:16868} Mourning's Rest · {area:17145} Cradle of Tranquility · {npc:255683} Shalla'kal · {npc:267109} Galvinquam Leafsyre
	["East past {area:16868} into the {area:17145}: {npc:255683}, the great cat, waits by the path, and {npc:267109} rests in the ruins just south of her."] = "{area:16868} kesimini geçip doğuya, {area:17145} içine git: büyük kedi {npc:255683} patikanın yanında bekliyor, {npc:267109} de onun hemen güneyindeki harabelerde dinleniyor.",

	-- Step 90: Lisbael Highfeather
	-- {npc:268168} Lisbael Highfeather
	["East across the Cradle to {npc:268168}."] = "Cradle'ı doğuya geçip {npc:268168} yanına git.",
