	-- {npc:267158} Jereman
	["North to the old bridge over the Cradle: touch the crow effigy on it and {npc:267158}, the crow wild god, appears."] = "Kuzeye, Cradle'ın üstündeki eski köprüye git: üstündeki karga heykeline dokun, karga vahşi tanrısı {npc:267158} belirir.",

