	["{npc:249234}'s camp"] = "{npc:249234} kampı",
	-- {npc:249234} Johun "Punchy" Dillas
	["North to {npc:249234} and his crates. Drive the skunks out from behind the crates without attacking them."] = "Kuzeye, {npc:249234} ve sandıklarının yanına git. Kokarcaları saldırmadan sandıkların arkasından çıkar.",

