	["Foxes"] = "Tilkiler",
	-- {npc:249234} Johun "Punchy" Dillas · {npc:255183} Jezerelle the Swaying · {npc:256830} Bannerwing Survivor
	["The Rustleaf Foxes are thick in the woods around {npc:249234}'s camp.\nCareful: {npc:255183} (61, rare) walks the woods north of the camp, and a {npc:256830} (60, rare) can turn up there too: leave them be."] = "Rustleaf Fox yaratıkları {npc:249234} kampının çevresindeki ormanda çok.\nDikkat: {npc:255183} (61, rare) kampın kuzeyindeki ormanda yürüyor, orada bir {npc:256830} (60, rare) da çıkabilir: onlara bulaşma.",

	-- Step 97: Kala'th
	-- {npc:255693} Kala'th
	["West across the Cradle to {npc:255693}, another of the wild gods."] = "Cradle'ı batıya geçip başka bir vahşi tanrı olan {npc:255693} yanına git.",

	-- Step 98: The burnt buildings
	["The burnt buildings"] = "Yanmış binalar",
	-- {npc:255693} Kala'th
	["The burnt buildings stand in the meadows east of {npc:255693}: the nails and brackets lie among the rubble."] = "Yanmış binalar {npc:255693} yanının doğusundaki çayırlarda duruyor: çiviler ve kelepçeler molozun arasında.",

