	["South to {npc:267113}, another wild god, at {area:16868}'s eastern edge."] = "Güneye, {area:16868} kesiminin doğu kenarındaki başka bir vahşi tanrı {npc:267113} yanına git.",
	-- {quest:92317} Stolen Life · {npc:256222} Ketharas
