	-- Step 102: Bones and stolen life
	["Bones and stolen life"] = "Kemikler ve çalınmış hayat",
	-- {area:16868} Mourning's Rest
	-- plural, as words: Fleshflay Raveners = {npc:249228} Fleshflay Ravener · Death Wailers = {npc:249226} Death Wailer · Spectral Frostwyrms = {npc:255691} Spectral Frostwyrm
	["The sun-bleached bones lie all over {area:16868}; the Fleshflay Raveners there carry the drop of stolen life.\nCareful: Death Wailers (61, rare elites) drift over {area:16868}: keep out of their way. Spectral Frostwyrms (61, elites) circle over the meadows around it: keep out from under them."] = "Güneşte ağarmış kemikler {area:16868} kesiminin her yanında yatıyor. Oradaki Fleshflay Ravener yaratıkları çalınmış hayat damlasını taşıyor.\nDikkat: Death Wailer yaratıkları (61, rare elit) {area:16868} üstünde süzülüyor: yollarından çekil. Spectral Frostwyrm yaratıkları (61, elit) çevresindeki çayırların üstünde dönüyor: altlarına girme.",

	-- Step 103: Final Death
	-- {area:16868} Mourning's Rest · {item:274411} Survivor's Torch · {npc:260148} Scourge Reanimator · {area:16848} Elderwild
	["Burn the bone pile at the south-eastern end of {area:16868} with the {item:274411}: the {npc:260148} that answers carries the amulet. The hand-in waits for the ride back to {area:16848} at the end of this guide.\nCareful: the {npc:260148} is level 59-60: burn the bone pile last, at full health, with the ruins around it cleared."] = "{area:16868} kesiminin güneydoğu ucundaki kemik yığınını {item:274411} ile yak: gelen {npc:260148} muskayı taşıyor. Teslim, bu rehberin sonunda {area:16848} kesimine dönüşü bekliyor.\nDikkat: {npc:260148} seviye 59-60: kemik yığınını en son, canın tamken ve çevresindeki harabeleri temizledikten sonra yak.",

	-- Step 104: Final Death
	-- {npc:260148} Scourge Reanimator · {area:16848} Elderwild
	["A group choice below level 58: the {npc:260148} that answers the burnt bone pile is level 59-60. Grouping up is advised. The hand-in waits for the ride back to {area:16848} at the end of this guide."] = "Seviye 58'in altında bir grup tercihi: yakılan kemik yığınına gelen {npc:260148} seviye 59-60. Grup kurman önerilir. Teslim, bu rehberin sonunda {area:16848} kesimine dönüşü bekliyor.",

	-- Step 105: Final Death
	-- {npc:260148} Scourge Reanimator · {npc:244511} Zet'gan · {area:16848} Elderwild
	["A group choice below level 58: the {npc:260148} that answers the burnt bone pile is level 59-60. Grouping up is advised. {npc:244511} takes the amulet on the ride back to {area:16848} at the end of this guide."] = "Seviye 58'in altında bir grup tercihi: yakılan kemik yığınına gelen {npc:260148} seviye 59-60. Grup kurman önerilir. Muskayı bu rehberin sonunda {area:16848} kesimine dönüşte {npc:244511} alır.",

	-- Step 107: Whisperfur
	-- {npc:255771} Whisperfur · {area:16868} Mourning's Rest
	["The last kitten, {npc:255771}, plays at the southern end of {area:16868}."] = "Son yavru kedi {npc:255771}, {area:16868} kesiminin güney ucunda oynuyor.",

