	-- {area:16867} Shrine of Aviana · {npc:260825} Phoebe Highfeather
	["East from the Cradle towards the {area:16867}, where the Wormwing harpies nest: a corrupted growth on the shrine's western slope starts a quest for {npc:260825}."] = "Cradle'dan doğuya, Wormwing harpy'lerinin yuva yaptığı {area:16867} kesimine doğru git: tapınağın batı yamacındaki bozulmuş bir sürgün {npc:260825} için bir görev başlatır.",
	["remove the corrupted knots on the trees just north-west of the shrine, on your way"] = "yolda, tapınağın hemen kuzeybatısındaki ağaçlarda bozulmuş düğümleri temizle",

