	-- {npc:267158} Jereman
	["On to the old bridge over the Cradle: touch the crow effigy on it and {npc:267158} appears again."] = "Cradle'ın üstündeki eski köprüye devam et: üstündeki karga heykeline dokun, {npc:267158} yine belirir.",
