	-- {npc:249234} Johun "Punchy" Dillas · {area:16866} Dae'gun
	["North-east across the Cradle to {npc:249234}'s camp at the edge of {area:16866}."] = "Cradle'ı kuzeydoğuya geçip {area:16866} kenarındaki {npc:249234} kampına git.",

	-- Step 121: Elaena Moonwhisper, Witherbeard and Yashiro
	-- {npc:263406} Elaena Moonwhisper · {npc:249052} Witherbeard · {npc:267121} Yashiro
	["{npc:263406}, {npc:249052} and {npc:267121}"] = "{npc:263406}, {npc:249052} ve {npc:267121}",
	-- {area:16866} Dae'gun · {npc:263406} Elaena Moonwhisper · {npc:249052} Witherbeard · {npc:267121} Yashiro
	["Into {area:16866}, north of the Cradle: the ruins of a Horde base, now held by demons. {npc:263406} and {npc:249052} camp at its western edge; {npc:267121}, a blademaster, waits a little east of them. Doomguards (elites, levels 58-59) walk among the demons: pull carefully."] = "Cradle'ın kuzeyindeki {area:16866} içine gir: artık iblislerin tuttuğu eski bir Horde üssünün harabeleri. {npc:263406} ve {npc:249052} batı kenarında kamp kurmuş. Bir blademaster olan {npc:267121} onların biraz doğusunda bekliyor. İblislerin arasında Doomguard'lar (elit, seviye 58-59) yürüyor: dikkatli çek.",

	-- Step 122: Maerion Thaelemaches
	-- {npc:267097} Maerion Thaelemaches · {area:16866} Dae'gun · {quest:97009} Maerion's Misery · {npc:267439} Doomguard Xarkul
	-- plural, as words: Defiling Hounds = {npc:249230} Defiling Hound · Legion Hulks = {npc:249238} Legion Hulk
	["North-east to {npc:267097} at the northern ruins of {area:16866}: take {quest:97009} so the Defiling Hounds drop their spikes while you work the other errands here.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps, and {npc:267439}, an elite (level 61), walks this corner: give them room."] = "Kuzeydoğuya, {area:16866} kesiminin kuzey harabelerindeki {npc:267097} yanına git: buradaki diğer işleri yaparken Defiling Hound yaratıklarının dikenlerini düşürmesi için {quest:97009} görevini al.\nDikkat: Legion Hulk yaratıkları (60, rare elit) {area:16866} kamplarında dolaşıyor, elit {npc:267439} (seviye 61) da bu köşede yürüyor: onlardan uzak dur.",

	-- Step 123: Renalard
	-- {area:16866} Dae'gun · {npc:259695} Renalard
	["South-east across {area:16866} to {npc:259695}, the wild god, indoors at its south-eastern edge."] = "{area:16866} içinden güneydoğuya, güneydoğu kenarında, kapalı bir yerdeki vahşi tanrı {npc:259695} yanına git.",
	-- {quest:92335} Ashes of the Legion Ascent · {npc:256222} Ketharas
	["{quest:92335}: for {npc:256222}, later in this guide"] = "{quest:92335}: bu rehberde daha sonra {npc:256222} için",

	-- Step 124: Dae'gun
	-- {area:16866} Dae'gun · {npc:259695} Renalard · {npc:265788} Kal'tinzan · {item:253249} Horde Flag · {object:656786} Troll Remains (no name in this language: may be words) · {quest:96998} Tribal Colors · {npc:255183} Jezerelle the Swaying · {npc:267439} Doomguard Xarkul
	-- plural, as words: Felguard Sentinels = {npc:249229} Felguard Sentinel · Defiling Hounds = {npc:249230} Defiling Hound · Legion Hulks = {npc:249238} Legion Hulk
	["Work west back through {area:16866}: the Felguard Sentinels and Defiling Hounds are everywhere, the hounds carry the essence, and the Horde base's rubble (wire, scrap and dung) lies all over it. Light the two bonfires on your way, scout the Horde tower in the middle, take Azgalor's ashes west of the tower, and pick up the abandoned supplies, a few just north-west of {npc:259695} and the rest in the western half: {npc:259695}'s tuft of fur, used on a demon, distracts it while you take them.\nHorde: the demons here also drop the Scraps of Horde Heraldry for {npc:265788}, the old {item:253249} stands in the camp north of the south bonfire, and the {object:656786} at the camp's eastern edge start {quest:96998}.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps: give them room. {npc:255183} (61, rare) walks the camp north of the south bonfire: keep away from her.\nCareful: Doomguards (elites, 58-59) stand among the demons, and {npc:267439} (elite, 61) walks the camp: pull the hounds and sentinels to you, away from them."] = "{area:16866} içinden batıya doğru ilerle: Felguard Sentinel ve Defiling Hound yaratıkları her yerde, özü köpekler taşıyor, Horde üssünün molozu (tel, hurda ve gübre) da her yana saçılmış. Yolda iki şenlik ateşini yak, ortadaki Horde kulesini keşfet, kulenin batısında Azgalor'un küllerini al ve terk edilmiş erzakları topla: birkaçı {npc:259695} yanının hemen kuzeybatısında, kalanı batı yarısında. {npc:259695} adlı NPC'nin tutam kürkü bir iblis üzerinde kullanılınca sen onları alırken iblisin dikkatini dağıtır.\nHorde: buradaki iblisler {npc:265788} için Scraps of Horde Heraldry de düşürür, eski {item:253249} güney şenlik ateşinin kuzeyindeki kampta duruyor, kampın doğu kenarındaki {object:656786} da {quest:96998} görevini başlatır.\nDikkat: Legion Hulk yaratıkları (60, rare elit) {area:16866} kamplarında dolaşıyor: onlardan uzak dur. {npc:255183} (61, rare) güney şenlik ateşinin kuzeyindeki kampta yürüyor: ondan uzak dur.\nDikkat: iblislerin arasında Doomguard'lar (elit, 58-59) duruyor, {npc:267439} (elit, 61) da kampta yürüyor: köpekleri ve sentinel'leri onlardan uzağa, kendine çek.",
	["Southeast Bonfire"] = "Southeast Bonfire",
	["South Bonfire"] = "South Bonfire",
	["scout the Horde tower"] = "Horde kulesini keşfet",
	-- {object:656786} Troll Remains (no name in this language: may be words) · {quest:96998} Tribal Colors · {npc:244511} Zet'gan · {area:16848} Elderwild
	["{object:656786}: {quest:96998}, for {npc:244511} in {area:16848}; keep it"] = "{object:656786}: {area:16848} kesimindeki {npc:244511} için {quest:96998}. Sakla",

	-- Step 126: Drawing Down the Malevolent
	-- {npc:263394} Bethra'zel the Feeble · {npc:252457} Mazzogore · {npc:263406} Elaena Moonwhisper
	["A group choice: {npc:263394} and {npc:252457} are level 60 elites until {npc:263406}'s eye drains them. Drain each one first, then fight it; players in our recordings killed both once drained. Grouping up is advised."] = "Bir grup tercihi: {npc:263394} ve {npc:252457}, {npc:263406} adlı NPC'nin gözü onları emene kadar 60. seviye elit. Önce her birini em, sonra dövüş. Kayıtlarımızdaki oyuncular emildikten sonra ikisini de öldürdü. Grup kurman önerilir.",

	-- Step 128: Bethra'zel the Feeble
	-- {npc:263394} Bethra'zel the Feeble · {npc:263406} Elaena Moonwhisper · {npc:252457} Mazzogore · {npc:267439} Doomguard Xarkul · {area:16866} Dae'gun
	-- plural, as words: Legion Hulks = {npc:249238} Legion Hulk
	["North-east to {npc:263394}. Drain him first: use {npc:263406}'s eye on him, and only then fight him. Undrained, he and {npc:252457} are level 60 elites. {npc:267439}, an elite (level 61), walks this corner of {area:16866}: keep out of his way.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps: give them room."] = "Kuzeydoğuya, {npc:263394} yanına git. Önce onu em: üzerinde {npc:263406} adlı NPC'nin gözünü kullan, ancak ondan sonra dövüş. Emilmeden o ve {npc:252457} 60. seviye elit. Elit {npc:267439} (seviye 61) {area:16866} kesiminin bu köşesinde yürüyor: yolundan çekil.\nDikkat: Legion Hulk yaratıkları (60, rare elit) {area:16866} kamplarında dolaşıyor: onlardan uzak dur.",

	-- Step 129: Maerion Thaelemaches
	-- {npc:267097} Maerion Thaelemaches · {area:16866} Dae'gun · {npc:263394} Bethra'zel the Feeble · {npc:267439} Doomguard Xarkul
	-- plural, as words: Defiling Hounds = {npc:249230} Defiling Hound · Legion Hulks = {npc:249238} Legion Hulk
	["North-east back to {npc:267097}, in the corner of {area:16866} where {npc:263394} stands: the Defiling Hounds around him drop any spikes you still need.\nCareful: Legion Hulks (60, rare elites) stomp through {area:16866}'s camps, and {npc:267439}, an elite (level 61), walks this corner: give them room."] = "Kuzeydoğuya, {area:16866} kesiminin {npc:263394} yaratığının durduğu köşesindeki {npc:267097} yanına dön: çevresindeki Defiling Hound yaratıkları hâlâ gereken dikenleri düşürür.\nDikkat: Legion Hulk yaratıkları (60, rare elit) {area:16866} kamplarında dolaşıyor, elit {npc:267439} (seviye 61) da bu köşede yürüyor: onlardan uzak dur.",

	-- Step 130: Mazzogore
	-- {npc:263426} Mazzogore the Weak · {area:16866} Dae'gun · {npc:263394} Bethra'zel the Feeble
	["South-west to {npc:263426}, in the middle of {area:16866}: drain him with the eye first, as {npc:263394}, then kill him. Undrained, he is a level 60 elite.\nCareful: Doomguards (elites, 58-59) stand around him: pull him out to you."] = "Güneybatıya, {area:16866} kesiminin ortasındaki {npc:263426} yanına git: {npc:263394} gibi onu da önce gözle em, sonra öldür. Emilmeden 60. seviye bir elit.\nDikkat: çevresinde Doomguard'lar (elit, 58-59) duruyor: onu kendine çek.",

